// В structured mode query — это объект, из которого мы берём строку запроса
const searchQuery = query.query; 
const url = 'http://searxng:8080/search?q=' + encodeURIComponent(searchQuery) + '&format=json';

try {
  const data = await this.helpers.httpRequest({
    method: 'GET',
    url: url,
    headers: { 'User-Agent': 'Mozilla/5.0 (compatible; n8n-bot/1.0)' },
    json: true
  });

  if (!data.results || data.results.length === 0) {
    return `По запросу "${searchQuery}" ничего не найдено.`;
  }

  const cleanResults = data.results.slice(0, 7).map(item => ({
    title: item.title || 'Без названия',
    url: item.url || '',
    snippet: item.content ? item.content.substring(0, 400) + '...' : 'Нет описания'
  }));

  return JSON.stringify(cleanResults);
} catch (error) {
  return "Ошибка поиска: " + error.message;
}
